// Aviso de véspera: só entregas que vencem exatamente daqui a `dias` dias.
const cfg = $('Configuração').first().json;
const row = $('Buscar prazos').first().json;
const parse = (v) => (typeof v === 'string' ? JSON.parse(v) : v);
const antecedencia = Number(cfg.dias);
// Só a data de entrega da publi (campo "fim" da campanha).
const TIPOS = ['prazo_marca'];
const itens = (parse(row.itens) || []).filter((i) => i.dias === antecedencia && TIPOS.includes(i.tipo));
const perfil = parse(row.perfil) || {};

if (!itens.length) return [];

const EMOJI = { entrega: '📲', prazo_marca: '📦', publicacao: '📣' };
const SEMANA = ['dom', 'seg', 'ter', 'qua', 'qui', 'sex', 'sáb'];
const fmtData = (iso) => {
  const [a, m, d] = iso.split('-').map(Number);
  return `${String(d).padStart(2, '0')}/${String(m).padStart(2, '0')} (${SEMANA[new Date(Date.UTC(a, m - 1, d)).getUTCDay()]})`;
};
const esc = (s) => String(s ?? '').replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
const appUrl = String(cfg.app_url || '').replace(/\/+$/, '');
const quando = antecedencia === 1 ? 'Amanhã' : `Em ${antecedencia} dias`;
const dia = fmtData(itens[0].data);
const quem = (i) => [i.marca, i.campanha].filter(Boolean).join(' — ') || 'Sem campanha';
const oque = (i) => (i.tipo === 'entrega' ? `Postagem: ${i.titulo}` : i.titulo);

// WhatsApp
const linhas = [`⏰ *${quando}, ${dia}, ${itens.length === 1 ? 'vence uma entrega' : `vencem ${itens.length} entregas`}*`, ''];
for (const i of itens) {
  linhas.push(`${EMOJI[i.tipo]} *${quem(i)}*`);
  linhas.push(`   ${oque(i)}`);
  if (appUrl && i.publi_id) linhas.push(`   ${appUrl}/#/campanhas/${i.publi_id}`);
}
const whatsapp = linhas.join('\n').trim();

// E-mail
const html = `<div style="font-family:Arial,Helvetica,sans-serif;max-width:640px;margin:auto;color:#222">
  <h2>⏰ ${quando}, ${dia}</h2>
  <ul style="padding-left:18px;font-size:15px">${itens.map((i) => {
    const link = appUrl && i.publi_id ? `${appUrl}/#/campanhas/${i.publi_id}` : '';
    const q = link ? `<a href="${esc(link)}" style="color:#7c3aed">${esc(quem(i))}</a>` : esc(quem(i));
    return `<li style="margin-bottom:8px">${EMOJI[i.tipo]} <strong>${q}</strong><br><span style="color:#555">${esc(oque(i))}</span></li>`;
  }).join('')}</ul>
</div>`;
const assunto = `${quando}, ${dia}: ${itens.length === 1 ? '1 entrega' : itens.length + ' entregas'} — ${[...new Set(itens.map((i) => i.marca).filter(Boolean))].join(', ')}`;

const emailPara = String(cfg.email_para || perfil.email || '').trim();
const numeros = String(cfg.whatsapp_numeros || perfil.whatsapp || '')
  .split(/[,;]/).map((n) => n.trim()).filter(Boolean)
  .map((n) => {
    if (n.includes('@')) return n;
    const d = n.replace(/\D/g, '');
    return d.length === 10 || d.length === 11 ? '55' + d : d;
  });

const base = { assunto, html, whatsapp, email_para: emailPara, total: itens.length };
return numeros.length
  ? numeros.map((numero) => ({ json: { ...base, numero } }))
  : [{ json: { ...base, numero: null } }];
